items.script:
(blockcontext, pageContext, item) => {
    let listValues = [];
    let settings = blockcontext.timelineSettings;
    let groupBy = (settings && settings.eventGrouping && settings.eventGrouping.groupBy) ? settings.eventGrouping.groupBy : " Mins";
    if (groupBy === "Mins") {
        for (let i = 1; i <= 60; i++) {
            listValues.push({
                "id": i,
                "label": i
            });
        }
    } else {
        for (let i = 1; i <= 24; i++) {
            listValues.push({
                "id": i,
                "label": i
            });
        }
    }

    return listValues;
}

selectedItems.script:
(blockcontext, pageContext, item) => {
    let settings = blockcontext.timelineSettings;
    let groupByValue = (settings && settings.eventGrouping && settings.eventGrouping.groupByValue) ? settings.eventGrouping.groupByValue : 5;
    return [groupByValue];
}

disabled.script:
(blockcontext, pageContext, item) => {
    let settings = blockcontext.timelineSettings;
    if (settings && settings.eventGrouping.enabled === true)
        return false;
    return true;
}
